import { IOperatorTheme } from '@game-studio/operator-theme';
import { Component, Prop, Vue } from 'vue-property-decorator';
import { OverlaysEventEmitter } from '../../event-emitter';
import { OPTIONS } from '../../options';

@Component({
    name: 'AutoWithdraw'
})
export default class AutoWithdraw extends Vue {
    public isVisible: boolean = false;

    @Prop({
        required: false,
        type: Object,
        default: () => OPTIONS.theme
    })
    public theme: IOperatorTheme;

    private title: string = '';
    private message: string = '';
    private button: string = '';
    private onClosed?: () => void;

    public created() {
        this.show = this.show.bind(this);
    }

    public mounted() {
        OverlaysEventEmitter.on('showAutoWithdraw', this.show);
        OverlaysEventEmitter.on('closeAutoWithdraw', this.hide);
    }

    public beforeDestroy() {
        OverlaysEventEmitter.off('showAutoWithdraw', this.show);
        OverlaysEventEmitter.off('closeAutoWithdraw', this.hide);
    }

    public show(onClosed?: () => void) {
        this.isVisible = true;
        this.title = '¡Enhorabuena!';
        this.message = 'Te animamos a que retires tu premio y comiences a disfrutarlo. Si tienes alguna duda, contacta con el Servicio de Atención al Cliente (800 600 132).';
        this.button = 'Cerca';
        this.onClosed = onClosed;
    }

    public close() {
        if (this.onClosed) {
            this.onClosed();
        }
        //TODO: SHOW LOADING SPINNER:
        // OverlaysEventEmitter.emit('showLoadingSpinner');
    }

    private hide() {
        this.isVisible = false;
        OverlaysEventEmitter.emit('hideLoadingSpinner');
        //TODO: Remove loading spinner
    }
}
